public static void ExportSameExam_2(long? sameExamID = null, long? examID = null, long? testScheduleID = null)
{
    string strFileName = Application.StartupPath + "\\Template\\SameExam_Phach.htm";
    string[] label = { "A", "B", "C", "D", "E", "F" };

    // lấy danh sách câu hỏi đang tick chọn
    //string strIDList = gvData.GetIDListSelected("QuestionID");
    //if (strIDList == "")
    //{
    //    MessageManager.Warning("Bạn chưa chọn dữ liệu để xuất");
    //    return;
    //}

    // lấy dữ liệu xuất
    EXM_Question obj = new EXM_Question();

    DataTable dtbSameExam = null;
    DataTable dtbPrint = null;
    DataTable dtbAnswerPrint = null;

    if (examID != null)
    {
        dtbSameExam = obj.GetDataTable("EXM_Exam_GetInfo", "@ExamID", examID);
        dtbPrint = obj.GetDataTable("EXM_ExamDetail_Print", "@ExamID", examID);
        dtbAnswerPrint = obj.GetDataTable("EXM_ExamDetail_Answer_Print", "@ExamID", examID);
    }
    else
    {
        dtbSameExam = obj.GetDataTable("EXM_SameExam_GetInfo", "@SameExamID", sameExamID);
        dtbPrint = obj.GetDataTable("EXM_SameExamDetail_Print", "@SameExamID", sameExamID);
        dtbAnswerPrint = obj.GetDataTable("EXM_SameExamDetail_Answer_Print", "@SameExamID", sameExamID);
    }


    if (dtbPrint == null || dtbSameExam == null || dtbAnswerPrint == null)
    {
        ErrorManager.Error("Việc tải dữ liệu bị lỗi!");
        return;
    }

    bool bolIsShowMarkOfQuestion = Convert.ToBoolean(dtbSameExam.Rows[0]["IsShowMarkOfQuestion"]); // có hiển thị thang điểm từng câu hỏi không

    // Tạo nội dung câu hỏi
    string strGroupByID_Prev = "";
    string strQuestionGroupID_Prev = "";

    string str = "";
    int i = 0; // i là thứ tự câu hỏi
    int g = 0; // g là thứ tự nhóm trong 1 phần, qua phần mới reset lại về 0

    foreach (DataRow drw in dtbPrint.Rows)
    {                
        #region Nhóm theo thành phần câu hỏi trong cấu trúc đề thi

        if (drw["GroupByID"].ToString() != strGroupByID_Prev)
        {
            // nếu qua phần mới thì reset lại thứ tự nhóm và thứ tự câu
            i = 0;
            g = 0;                     

            string strGroupByName = drw["GroupByContent"].ToString(); // lấy nội dung mô tả của thành phần đề thi để view
            if (strGroupByName != "")
            {
                //str += "<p><div class='GroupByName'> <table><tr><td>" + strGroupByName + "</td></tr></table></div></p>"; // kiểu cũ cần border background mới dùng
                str += "<p><div class='GroupByName'>" + strGroupByName + "</div></p>"; // dùng table hay bị tăng độ pacing ko muốn nên phải hạn chế
            }
            strGroupByID_Prev = drw["GroupByID"].ToString();
        }

        #endregion

        #region Nhóm theo nhóm câu hỏi

        if (drw["QuestionGroupID"].ToString() != strQuestionGroupID_Prev)
        {
            g++; // qua nhóm mới thì tăng thứ tự nhóm lên
            // nếu sau này qua nhóm mới mà có reset lại thứ tự câu hỏi thì chèn ở đây


            string strOtherQuestionGroup = drw["OtherQuestionGroupContentHtml"].ToString(); // cột trái
            string strQuestionGroup = drw["QuestionGroupContentHtml"].ToString(); // cột phải
            string strGroupValue = strOtherQuestionGroup + strQuestionGroup;

            if (strGroupValue != "")
            {
                #region  Chèn thứ tự nhóm câu (nếu Phần thi này đánh số theo nhóm và có hơn 1 nhóm trong phần này)

                int iP = StringUtil.GetDetailPosTab(strGroupValue, "p"); // tìm vị trí đuối của thẻ <p> đầu tiên, vì thẻ có css nên không tìm theo kiểu đơn giản IndexOf được

                if (Convert.ToBoolean(drw["FollowQuestionGroup"]) && Convert.ToInt32(drw["GroupCount_OfPart"]) > 1)
                {
                    string strOrder = "<span class='GroupIndex'>" + g.ToString() + ".</span> ";
                    if (iP >= 0)
                        strGroupValue = strGroupValue.Insert(iP, strOrder);
                    else
                        strGroupValue = strOrder + strGroupValue;
                }
                //else // nếu ko chèn thứ tự nhóm thì chèn thêm vài khoản trắng
                //{
                //    if (iP >= 0)
                //        strGroupValue = strGroupValue.Insert(iP, " &nbsp; &nbsp; &nbsp; ");
                //    else
                //        strGroupValue = "<span> &nbsp; &nbsp; &nbsp;</span>" + strGroupValue;
                //}

                #endregion

                str += "<div class='QuestionGroupContent'>" + strGroupValue + "</div>";
            }

            strQuestionGroupID_Prev = drw["QuestionGroupID"].ToString();
        }

        #endregion

        // nếu là điền khuyết vào nhóm câu thì bỏ qua đoạn này luôn
        // tạm thời câu true/false cũng bỏ qua và cho vào nhóm luôn (lát tính sau)
        if (Convert.ToInt32(drw["QuestionTypeID"]) == EXM_QuestionType.FillBlank || Convert.ToInt32(drw["QuestionTypeID"]) == EXM_QuestionType.BOOL)
        {
            continue;
        }


        #region  Câu hỏi

        i++; // thứ tự câu hỏi
        string value = drw["QuestionContentHtml"].ToString();

        #region  Chèn thêm thứ tự câu hỏi nếu (nếu phần này theo nhóm hoặc chỉ có 1 câu hỏi thì bỏ qua)

        int p = StringUtil.GetDetailPosTab(value, "p"); // tìm vị trí đuối của thẻ <p> đầu tiên, vì thẻ có css nên không tìm theo kiểu đơn giản IndexOf được

        if (!Convert.ToBoolean(drw["FollowQuestionGroup"]) && Convert.ToInt32(drw["QuestionCount_OfPart"]) > 1)
        {

            // Dạng đặc biệt là đề tự luận, thực hành, vấn đáp số câu ít, học hay thụt đầu câu hỏi và có thang điểm, sau đó xuống hàng thụt vô rồi đến nội dung câu hỏi
            if (bolIsShowMarkOfQuestion)
            {
                string strMark = drw["Mark"].ToString() != "" ? Convert.ToDouble(drw["Mark"]).ToString("#,###.##") : "";
                string strOrder = string.Format("<br>&nbsp;  &nbsp;  &nbsp;  &nbsp; <span class='QuestionIndex'>Câu {0}:</span><span class='QuestionMark'> ({1} điểm)</span>", i, strMark); // do câu tự luận ít nên cứ enter khi qua câu mới (gán cứng)
                if (p >= 0)
                    value = strOrder + value.Insert(p, "&nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp; "); // chèn thụt đầu dòng vô p
                else
                    value = strOrder + "<br> &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp; " + value; // không có p thì tự xuống hàng và cộng chuỗi bình thường 
            }
            else // không chèn thang điểm thì vẫn như cũ: Câu hỏi x: nội dung câu hỏi....
            {
                string strOrder = "<span class='QuestionIndex'>Câu " + i.ToString() + ":</span> ";
                if (p >= 0)
                    value = value.Insert(p, strOrder);
                else
                    value = strOrder + value;
            }
        }
        else // nếu ko chèn thứ tự nhóm thì chèn thêm vài khoản trắng
        {
            // Dạng đặc biệt là đề tự luận, thực hành, vấn đáp số câu ít, học hay thụt đầu câu hỏi và có thang điểm, sau đó xuống hàng thụt vô rồi đến nội dung câu hỏi
            if (bolIsShowMarkOfQuestion)
            {
                string strMark = drw["Mark"].ToString() != "" ? Convert.ToDouble(drw["Mark"]).ToString("#,###.##") : "";
                string strOrder = string.Format("&nbsp;  &nbsp;  &nbsp;  &nbsp; <span class='QuestionIndex'>Câu hỏi:</span><span class='QuestionMark'> ({0} điểm)</span>", strMark);
                if (p >= 0)
                    value = strOrder + value.Insert(p, "&nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp; "); // chèn thụt đầu dòng vô p
                else
                    value = strOrder + "<br> &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp; " + value; // không có p thì tự xuống hàng và cộng chuỗi bình thường 
            }
            else // không chèn thang điểm thì chỉ thêm khoản trắng
            {
                if (p >= 0)
                    value = value.Insert(p, " &nbsp; &nbsp; &nbsp; ");
                else
                    value = " &nbsp; &nbsp; &nbsp; " + value;
            }
        }

        #endregion


        str += value;

        #endregion

        #region Câu trả lời (chỉ dùng cho dạng chọn 1 hoặc chọn nhiều thôi)

        if (Convert.ToInt32(drw["QuestionTypeID"]) == EXM_QuestionType.OPTION || Convert.ToInt32(drw["QuestionTypeID"]) == EXM_QuestionType.CHECK)
        {
            int intAnswerCol = Convert.ToInt32(drw["AnswerCol"]); // số cột đáp án
            string width = (100 / intAnswerCol) + "%";


            dtbAnswerPrint.DefaultView.RowFilter = "QuestionID = '" + drw["QuestionID"].ToString() + "'";
            DataTable dtb = dtbAnswerPrint.DefaultView.ToTable();
            string strAnswer = "<table class='answer-content' width='100%'>";
            int j = 0;
            foreach (DataRow row in dtb.Rows)
            {
                value = row["AnswerContentHtml"].ToString();

                // chèn nhãn a,b,c,d
                string strLabel = "<span class='answer-label'> &nbsp; &nbsp; " + label[j] + ". </span>";
                int p1 = StringUtil.GetDetailPosTab(value, "p"); // tìm vị trí đuối của thẻ <p> đầu tiên, vì thẻ có css nên không tìm theo kiểu đơn giản IndexOf được
                if (p1 >= 0)
                {
                    value = value.Insert(p1, strLabel);
                }
                else
                    value = strLabel + value;

                // chèn dáp án đúng                    
                //if (Convert.ToBoolean(row["IsCorrect"]))
                //{
                //    string strCorrect = " <span class='answer-correct'>(Đúng)</span> ";

                //    int p2 = value.LastIndexOf("</p>");
                //    if (p2 >= 0)
                //    {
                //        value = value.Insert(p2, strCorrect);
                //    }
                //    else
                //        value = value + strCorrect;
                //}

                if (j % intAnswerCol == 0)
                    strAnswer += "<tr>";

                strAnswer += string.Format("<td valign='top' style='width:{0}'>{1}</td>", width, value);
                j++;

                if (j % intAnswerCol == 0)
                    strAnswer += "</tr>";
            }

            strAnswer += "</table>";

            str += strAnswer; // cộng câu trả lời vào

            if (i == 40)
                i = 40;
        }

        #endregion
    }

    // đọc file template và fill giá trị vào
    DataRow drwSameExam = dtbSameExam.Rows[0];
    string strFileContent = Libs.Files.ReadFile(strFileName);
    strFileContent = strFileContent.Replace("{DETAIL}", str);

    if (Convert.ToInt32(drwSameExam["MethodTestID"]) == 2) // trắc nghiệm
        strFileContent = strFileContent.Replace("{StudentInfo}", "<br />Họ tên sinh viên:……………………………………………………, MSSV:…………………………");
    else
        strFileContent = strFileContent.Replace("{StudentInfo}", "");

    strFileContent = strFileContent.Replace("{ExamType}", "Kỳ thi kết thúc môn học/mô đun".ToUpper()); // drwSameExam["ExamType"].ToString());
    strFileContent = strFileContent.Replace("{SubjectName}", drwSameExam["SubjectName"].ToString().ToUpper());
    strFileContent = strFileContent.Replace("{TimeLen}", drwSameExam["TimeLen"].ToString() + " phút");
    strFileContent = strFileContent.Replace("{YearText}", drwSameExam["YearText"].ToString());
    strFileContent = strFileContent.Replace("{Semester}", drwSameExam["Semester"].ToString());            
    strFileContent = strFileContent.Replace("{SameExamCodeText}", drwSameExam["SameExamCodeText"].ToString()); // mã chữ của đề tương đương            

    //(phần ghi chú được dùng tài liệu hay không, hoặc hình đính kèm cho đề thực hành sẽ gán ở đây)
    strFileContent = strFileContent.Replace("{ExamContentHtml}", drwSameExam["ExamContentHtml"].ToString()); // nội dung hướng dẫn làm bài trong đề thi gốc


    // thông tin lớp
    strFileContent = strFileContent.Replace("{TrainingLevelName}", "............"); // drwSameExam["TrainingLevelName"].ToString());
    strFileContent = strFileContent.Replace("{ClassName}", "............");// drwSameExam["ClassName"].ToString());
    strFileContent = strFileContent.Replace("{CourseName}", "............"); //drwSameExam["CourseName"].ToString());
    strFileContent = strFileContent.Replace("{OrderTest}", "..........");
    strFileContent = strFileContent.Replace("{TestMethodName}", "............"); // drwSameExam["TestMethodName"].ToString());
    strFileContent = strFileContent.Replace("{TestDate}", "............"); // drwSameExam["TestDate"].ToString());

    // cơ quan
    string strReport_Header = SYS_SettingService.GetStringValue("Report_Header_Text");
    string strReport_Header2 = SYS_SettingService.GetStringValue("Report_Header2_Text");
    string strReport_Place = SYS_SettingService.GetStringValue("Report_Place");

    strFileContent = strFileContent.Replace("{HEADER}", strReport_Header);
    strFileContent = strFileContent.Replace("{HEADER2}", strReport_Header2.Replace("TRƯỜNG CAO ĐẲNG CỘNG ĐỒNG ĐỒNG THÁP","TRƯỜNG CĐCĐ ĐỒNG THÁP"));
    strFileContent = strFileContent.Replace("{PLACE}", strReport_Place);

    strFileContent = strFileContent.Replace("<p></p>", "");
    strFileContent = strFileContent.Replace("<p class=\"MsoNormal\">&nbsp;</p>", "");



    // tên tập tin mặc định
    string strDefaultFileName = Libs.Common.FilterFileName("De thi phach " + drwSameExam["SameExamCodeText"]);

    // Setting page
    DevExpress.XtraRichEdit.RichEditControl editor = new DevExpress.XtraRichEdit.RichEditControl();
    editor.HtmlText = strFileContent.Replace("<p>&nbsp;</p>", "").Replace("margin:12pt 0pt 12pt 0pt", "margin:0pt 0pt 0pt 0pt").Replace("line-height:150%", "line-height:100%").Replace("margin-top:3.0pt", "margin-top:0.0pt").Replace(";line-height:", ";line-height_:");

    // Set page margins cho đề thi có phách (dùng margin từ CSS template)
    editor.Document.Unit = DevExpress.XtraRichEdit.DocumentUnit.Centimeter;
    editor.Document.Sections[0].Page.PaperKind = System.Drawing.Printing.PaperKind.A4;
    editor.Document.Sections[0].Page.Landscape = false;
    editor.Document.Sections[0].Margins.Left = 2.0f;
    editor.Document.Sections[0].Margins.Right = 1.8f;
    editor.Document.Sections[0].Margins.Bottom = 1.6f;
    editor.Document.Sections[0].Margins.Top = 2.0f;

    DevExpress.XtraRichEdit.API.Native.CharacterProperties props = editor.Document.BeginUpdateCharacters(editor.Document.Range);
    //props.FontSize = 14;
    //props.ForeColor = Color.Black;
    editor.Document.EndUpdateCharacters(props);

    #region Đánh số trang

    DevExpress.XtraRichEdit.PageBasedRichEditView currentView = editor.ActiveView as DevExpress.XtraRichEdit.PageBasedRichEditView;
    if (currentView.PageCount > 1)
    {
        DevExpress.XtraRichEdit.API.Native.Section firstSection = editor.Document.Sections[0];
        DevExpress.XtraRichEdit.API.Native.SubDocument doc = firstSection.BeginUpdateFooter();
        doc.InsertText(doc.CreatePosition(doc.Range.End.ToInt()), "Trang ");
        doc.Fields.Add(doc.CreatePosition(doc.Range.End.ToInt()), "PAGE");
        doc.Fields.Update();
        firstSection.EndUpdateFooter(doc);
    }
    #endregion

    editor.Options.DocumentSaveOptions.DefaultFormat = DevExpress.XtraRichEdit.DocumentFormat.OpenXml;
    editor.Options.DocumentSaveOptions.DefaultFileName = strDefaultFileName;

    editor.SaveDocumentAs();
}


