private static void SetPage2CutReserveHeader(DevExpress.XtraRichEdit.RichEditControl editor, float reserveHeightCm)
{
    DevExpress.XtraRichEdit.API.Native.Section section = editor.Document.Sections[0];
    section.DifferentFirstPageHeaderFooter = true;

    DevExpress.XtraRichEdit.API.Native.SubDocument firstHeader = section.BeginUpdateHeader(DevExpress.XtraRichEdit.API.Native.HeaderFooterType.First);
    if (firstHeader.Range.Length > 0)
        firstHeader.Delete(firstHeader.Range);
    section.EndUpdateHeader(firstHeader);

    DevExpress.XtraRichEdit.API.Native.SubDocument primaryHeader = section.BeginUpdateHeader(DevExpress.XtraRichEdit.API.Native.HeaderFooterType.Primary);
    if (primaryHeader.Range.Length > 0)
        primaryHeader.Delete(primaryHeader.Range);

    float lineHeightCm = 0.45f;
    int lineCount = (int)Math.Ceiling(reserveHeightCm / lineHeightCm);
    string blankLines = "";
    for (int i = 0; i < lineCount; i++)
        blankLines += "\r\n";

    primaryHeader.InsertText(primaryHeader.Range.Start, blankLines);

    DevExpress.XtraRichEdit.API.Native.ParagraphProperties paraProps = primaryHeader.BeginUpdateParagraphs(primaryHeader.Range);
    paraProps.LineSpacingType = DevExpress.XtraRichEdit.API.Native.LineSpacingType.Exactly;
    paraProps.LineSpacing = lineHeightCm;
    paraProps.SpacingBefore = 0f;
    paraProps.SpacingAfter = 0f;
    primaryHeader.EndUpdateParagraphs(paraProps);

    section.EndUpdateHeader(primaryHeader);
}

