private static void InsertPage2CutReserve(DevExpress.XtraRichEdit.RichEditControl editor)
{
    const string markerText = "[[PAGE2CUT]]";
    DevExpress.XtraRichEdit.API.Native.Document document = editor.Document;
    DevExpress.XtraRichEdit.API.Native.DocumentRange[] found = document.FindAll(markerText, DevExpress.XtraRichEdit.API.Native.SearchOptions.None);
    if (found == null || found.Length == 0)
        return;

    DevExpress.XtraRichEdit.DocumentPosition insertPos = found[0].Start;
    document.Delete(found[0]);

    document.InsertPageBreak(insertPos);

    DevExpress.XtraRichEdit.API.Native.Table reserveTable = document.Tables.Create(insertPos, 1, 1);
    reserveTable.Rows[0].Height = 7.0f;
    reserveTable.Rows[0].HeightType = DevExpress.XtraRichEdit.API.Native.HeightType.Exact;
    reserveTable.PreferredWidthType = DevExpress.XtraRichEdit.API.Native.WidthType.FiftiethsOfPercent;
    reserveTable.PreferredWidth = 5000;

    DevExpress.XtraRichEdit.API.Native.TableCell cell = reserveTable.Rows[0].Cells[0];
    DevExpress.XtraRichEdit.API.Native.TableBorders borders = reserveTable.Borders;
    borders.Top.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.Single;
    borders.Bottom.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.Single;
    borders.Left.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.Single;
    borders.Right.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.Single;
    borders.InsideHorizontal.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.None;
    borders.InsideVertical.LineStyle = DevExpress.XtraRichEdit.API.Native.TableBorderLineStyle.None;

    document.InsertText(cell.Range.Start, " ");
}

